create type gov_repo.ai_system_lifecycle as enum ('concept','development','testing','pre_market_review','conformity_assessed','production','under_significant_modification','post_market_surveillance','decommissioned');
comment on type gov_repo.ai_system_lifecycle is 'Full AI System lifecycle per EU AI Act Art. 17 Quality Management System. Distinct from gov_repo.system_status (M006 stub) which has 4 values. pre_market_review → conformity_assessed → CE marking eligible (Art. 43). under_significant_modification: Art. 83 — a significant modification resets the conformity assessment requirement. post_market_surveillance: Art. 72 — active surveillance after decommission.';
create type gov_repo.ce_marking_status as enum ('not_applicable','not_started','in_progress','marked','suspended','withdrawn');
comment on type gov_repo.ce_marking_status is 'CE marking lifecycle per EU AI Act Art. 47. Only applicable to ai_act_risk_class = ''high''. marked = CE marking physically/digitally affixed per Art. 47(1). withdrawn = Art. 47(4) — competent authority ordered withdrawal.';
create type gov_repo.annex_iii_sector as enum ('biometric_identification','critical_infrastructure','education_vocational_training','employment_worker_management','essential_services_benefits','law_enforcement','migration_asylum_border','administration_of_justice','not_annex_iii');
comment on type gov_repo.annex_iii_sector is 'EU AI Act Annex III high-risk use case classification. If annex_iii_sector != ''not_annex_iii'', the system is presumptively high-risk and ai_act_risk_class MUST be ''high'' unless Art. 6(3) exception applies. Financial services (credit scoring) maps to ''essential_services_benefits''.';
create type gov_repo.gpai_tier as enum ('not_gpai','gpai_standard','gpai_systemic_risk');
comment on type gov_repo.gpai_tier is 'GPAI model classification per EU AI Act Title VIII. gpai_standard: Art. 53 obligations — transparency, copyright policy, technical docs. gpai_systemic_risk: Art. 55 obligations — adversarial testing, incident reporting, cybersecurity measures, energy efficiency reporting. Threshold: training computation > 10^25 FLOPs (Art. 51(1)(a)).';
create type gov_repo.provider_role as enum ('provider','deployer','provider_and_deployer','importer','distributor');
comment on type gov_repo.provider_role is 'Organisation''s role in the AI value chain per EU AI Act Art. 3. Determines which obligations apply (Art. 16 = provider, Art. 26 = deployer). Internal AI systems built and deployed by same organisation = provider_and_deployer. Obligations cascade: provider obligations are more extensive than deployer obligations.';
do $$ begin if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='system_status') then create type gov_repo.system_status as enum ('development','testing','production','decommissioned'); end if; end $$;
do $$ begin if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='dora_criticality') then create type gov_repo.dora_criticality as enum ('critical','high','medium','low'); end if; end $$;
do $$ begin if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='incident_severity') then create type gov_repo.incident_severity as enum ('critical','high','medium','low'); end if; end $$;
do $$ begin if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='incident_status') then create type gov_repo.incident_status as enum ('reported','investigating','mitigated','resolved','closed'); end if; end $$;
do $$ begin if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='provider_service_type') then create type gov_repo.provider_service_type as enum ('cloud_infrastructure','foundation_model_api','saas_platform','data_provider','managed_service'); end if; end $$;;
